    def raise_dialog(self, title, message, description, needretry=False):
        try:
            msg = QMessageBox(self)
            msg.setText(message)
            msg.setInformativeText(description)
            msg.setWindowTitle(title)
            if needretry:
                self.raise_errorflag()
                msg.setStandardButtons(QMessageBox.Retry | QMessageBox.Cancel)
                self.ftpDownloadTaskThread.quit()
                self.ftpDownloadTaskThread.terminate()
                self.ftpDownloadTaskThread.wait()
            else:
                msg.setStandardButtons(QMessageBox.Close)
                self.ftpDownloadTaskThread.quit()
            retval = msg.exec()
            if retval == QMessageBox.Retry:
                self.errorflag = False
                self.define_thread()
                self.start_thread()
            elif retval == QMessageBox.Cancel or QMessageBox.Close:
                self.cancel_operation()
                self.retstatus = 'ERROR'
                self.close()

        except Exception as msg:
            logging.debug('error' + msg)

    def raise_errorflag(self):
        self.errorflag = True

    def update_dialog_title(self,index : int,status : ftpDownloadDialogThread.downloadDialogStatus,filesize = None):
        index = f"{index+1}/{len(self.ftpQueueManager.queue_list)}"

        if status == downloadDialogStatus.analyzing:
            self.dialogLabel.setText(f"Analyzing file {index}")

        if status == downloadDialogStatus.downloading:
            self.dialogLabel.setText(f"Downloading file {index}" + f' - {filesize}' if filesize else "")

        if status == downloadDialogStatus.cleanup:
            self.dialogLabel.setText(f"Cleaning up file {index}")

        QtWidgets.QApplication.processEvents()

    # CANCEL OPERATION HANDLER
    def cancel_button_action(self):
        cancel_msg = "Are you sure you want to cancel the operation?"
        reply = QMessageBox()
        reply.setText(cancel_msg)
        reply.setIcon(QMessageBox.Question)
        reply.setWindowTitle("Cancel download")
        reply.setStandardButtons(QMessageBox.Cancel | QMessageBox.No)
        reply.setDefaultButton(QMessageBox.No)
        reply = reply.exec_()

        if reply == QMessageBox.Cancel:
            self.raise_errorflag()
            self.ftpDownloadTaskThread.quit()
            self.ftpDownloadTaskThread.terminate()
            self.ftpDownloadTaskThread.wait()
            self.cancel_operation()
            self.retstatus = 'CANCEL'
            self.close()

    def cancel_operation(self):
        """
        In this operation remove all folders from QueueList.
        :return:
        """
        self.ftpDownloadTaskThread.quit()
        self.ftpDownloadTaskThread.terminate()
        self.ftpDownloadTaskThread.wait()

    # PROGRESS BAR CONTROLLER
    def set_progressbar_max_value(self,value):
        self.progressBar.setMaximum(round(value))

    def update_progressbar_value(self,value):
        self.progressBar.setValue(round(value))

    def add_to_progressbar_current_value(self,value):
        self.progressBar.setValue(
            round(value) + self.progressBar.value()
        )

    # THREAD CONTROLLER
    def download_finished(self):
        if not self.errorflag:
            self.ftpDownloadTaskThread.quit()
            self.ftpDownloadTaskThread.terminate()
            self.ftpDownloadTaskThread.wait()
            failed = []
            for item in self.ftpDownloadTaskThread.ftpQueueManager.queue_list:
                if item.status not in [ftpCourseStatus.finished,]:  # IF COURSE IS NOT FINISHED OR CLEANUP
                    failed.append(item)
            if failed:
                self.ftpDownloadTaskThread.ftpQueueManager.remove_failed_files()
                msg = QMessageBox(self)
                message = f"Failed to download or process {len(failed)} item(s) from queue"
                msg.setText(message)
                msg.setInformativeText(
                    "".join(f'{index + 1} - {item.file_directory}\n' for index, item in enumerate(failed)))
                msg.setWindowTitle('Completed downloading files.')
                msg.setStandardButtons(QMessageBox.Ok)
                msg.exec_()
            self.retstatus = 'COMPLETED'
            self.close()

    def define_thread(self):
        self.ftpDownloadTaskThread = ftpDownloadDialogThread.ftpDownloadThread(queuemanager=self.ftpQueueManager)

        self.ftpDownloadTaskThread.update_progress_bar_value.connect(self.update_progressbar_value)
        self.ftpDownloadTaskThread.max_progress_bar_value.connect(self.set_progressbar_max_value)
        self.ftpDownloadTaskThread.add_to_progressbar_current_value.connect(self.add_to_progressbar_current_value)

        self.ftpDownloadTaskThread.update_dialog_title.connect(self.update_dialog_title)
        self.ftpDownloadTaskThread.raise_dialog.connect(self.raise_dialog)
        self.ftpDownloadTaskThread.raise_errorflag.connect(self.raise_errorflag)

        self.ftpDownloadTaskThread.finished.connect(self.download_finished)

    def start_thread(self):
        try:
            self.ftpDownloadTaskThread.start()
        except Exception as msg:
            logging.debug(msg)
